        public void OnHogaReceived(string windowId, HogaData data)
        {
            if (data == null)
                return;

            if (Context == null || string.IsNullOrWhiteSpace(Context.Code))
                return;

            if (data.Code != Context.Code)
                return;

            lock (_latestHogaLock)
            {
                _latestHogaForAutoTrade = data;
            }

            // 호가 UI는 너무 자주 갱신하지 않는다.
            if ((DateTime.Now - _lastHogaUiUpdateTime).TotalMilliseconds < 300)
                return;

            _lastHogaUiUpdateTime = DateTime.Now;

            Application.Current.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    if (Context == null || string.IsNullOrWhiteSpace(Context.Code))
                        return;

                    if (data.Code != Context.Code)
                        return;

                    AskList.Clear();
                    foreach (var item in data.Asks)
                        AskList.Add(item);

                    BidList.Clear();
                    foreach (var item in data.Bids)
                        BidList.Add(item);

                    TotalAskQty = data.TotalAskQty;
                    TotalBidQty = data.TotalBidQty;
                }));
        }
