        private void FlushDbOnClose()
        {
            try
            {
                _performanceRefreshTimer.Stop();
                _performanceRefreshTimer.Tick -= PerformanceRefreshTimer_Tick;

                Db?.FlushAllPending();
                Db?.BuildAndSaveDailyPerformance(DateTime.Today);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[창 종료 Flush 실패] {ex.Message}");
            }
        }

