        private bool _isInitialized = false; // 중복 실행 방지 플래그

        private void Kiwoom_OnLogin(bool success)
        {
            if (!success) { AddLog("❌ 로그인 실패"); return; }

            if (_isInitialized) return;

            _isInitialized = true;
            AddLog("🔑 로그인 세션 확인 완료");
            FetchAccountList();
            _marketApi.RegisterMarketIndexRealtime(this.WindowId);
        }

