        private void Kiwoom_OnMarketIndexReceived(MarketIndexInfo index)
        {
            if (index == null || string.IsNullOrWhiteSpace(index.Code))
                return;

            Application.Current.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    if (index.Code == "001")
                        Kospi = index;
                    else if (index.Code == "101")
                        Kosdaq = index;
                    else
                        return;

                    var environment = MarketEnvironmentEvaluator.Create(Kospi, Kosdaq);

                    MarketTrendText = environment.Description;

                    _autoTradeController?.UpdateMarketEnvironment(environment);

                    string trendKey =
                        $"{environment.Trend}_{environment.AverageChangeRate:F1}_{environment.MarketRiskScore:F0}_{environment.MarketSupportScore:F0}";

                    bool shouldLog =
                        trendKey != _lastMarketAnalysisLogKey ||
                        (DateTime.Now - _lastMarketAnalysisLogTime).TotalSeconds >= 30;

                    if (!shouldLog)
                        return;

                    _lastMarketAnalysisLogKey = trendKey;
                    _lastMarketAnalysisLogTime = DateTime.Now;

                    AddAutoTradeAnalysisLog(
                        $"[시장분석] " +
                        $"상태={environment.Trend} | " +
                        $"KOSPI={environment.KospiChangeRate:F2}% | " +
                        $"KOSDAQ={environment.KosdaqChangeRate:F2}% | " +
                        $"시장평균={environment.AverageChangeRate:F2}% | " +
                        $"위험={environment.MarketRiskScore:F0} | " +
                        $"지지={environment.MarketSupportScore:F0} | " +
                        $"진입점수보정={environment.EntryScoreAdjustment:+0;-0;0} | " +
                        $"수량배율={environment.PositionSizeMultiplier:F2} | " +
                        $"손절배율={environment.StopLossMultiplier:F2} | " +
                        $"익절배율={environment.TakeProfitMultiplier:F2} | " +
                        $"트레일링배율={environment.TrailingMultiplier:F2}");
                }));
        }
