        private void OpenNewWindow()
        {
            MainWindow newWindow = new MainWindow();

            newWindow.Width = 1920;
            newWindow.Height = 1080;
            newWindow.WindowStartupLocation = WindowStartupLocation.CenterScreen;

            if (newWindow.DataContext is MainWindowViewModel targetVm)
            {
                targetVm.ScreenNo = _marketApi.GetScreenNo();

                targetVm.ApplyParentAccountContext(
                    SelectedAccount,
                    CurrentBalance,
                    AccountHoldings,
                    OrderHistory);
            }

            newWindow.Title = $"MoneyCreator - 새 작업창 ({DateTime.Now:HH:mm:ss})";

            newWindow.Show();
        }

        public void UpdateSearchResults(string query)
        {
            SearchResults.Clear();

            if (string.IsNullOrWhiteSpace(query) || query.Length < 2)
            {
                IsSearchPopupOpen = false;
                return;
            }

            var all = _marketApi.GetTotalSymbolList();
            if (all == null || all.Count == 0)
            {
                IsSearchPopupOpen = false;
                return;
            }

            int added = 0;

            foreach (var s in all)
            {
                if (s == null || string.IsNullOrWhiteSpace(s.Name))
                    continue;

                if (!s.Name.Contains(query))
                    continue;

                SearchResults.Add(s);

                if (++added >= 10)
                    break;
            }

            bool shouldOpen = SearchResults.Count > 0;

            Application.Current.Dispatcher.BeginInvoke(
                new Action(() =>
                {
                    IsSearchPopupOpen = shouldOpen;
                }),
                DispatcherPriority.Background);
        }
