            // GetConnectState() 리턴값: 0(미연결), 1(연결완료)
            return _api.GetConnectState() == 1;
        }
        public void AddLog(string msg)
        {
            try
            {
                Application.Current?.Dispatcher.BeginInvoke(new Action(() =>
                {
                    Logs.Insert(0, $"[{DateTime.Now:HH:mm:ss}] {msg}");
                    if (Logs.Count > 100) Logs.RemoveAt(100);
                }));
            }
            catch { }
        }
        private DateTime _lastAnalysisLogTime = DateTime.MinValue;
        private const int MaxAutoTradeAnalysisLogCount = 30;

        public void AddAutoTradeAnalysisLog(string msg)
        {
            if (string.IsNullOrWhiteSpace(msg))
                return;

            bool isTickAnalysis = msg.StartsWith("[틱분석]");
            bool isTradeSignal =
                msg.Contains("판단=Buy") ||
                msg.Contains("판단=Sell") ||
                msg.Contains("Action=Buy") ||
                msg.Contains("Action=Sell");

            if (!isTickAnalysis && !isTradeSignal)
            {
                if ((DateTime.Now - _lastAnalysisLogTime).TotalMilliseconds < 500)
                    return;

                _lastAnalysisLogTime = DateTime.Now;
            }

            Application.Current?.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    UpdateTradeAnalysisCardFromLog(msg);

                    AutoTradeAnalysisLogs.Insert(0, msg);

                    while (AutoTradeAnalysisLogs.Count > MaxAutoTradeAnalysisLogCount)
                        AutoTradeAnalysisLogs.RemoveAt(AutoTradeAnalysisLogs.Count - 1);
                }));
        }
