        // 1. 핵심 로직을 별도 메서드로 추출
        public async Task LoadSymbolDataAsync(Symbol symbol, bool waitHoldingLoad = true)
        {
            if (symbol == null)
                return;

            if (FocusOpenedSymbolWindow(symbol.Code))
                return;

            string previousCode = Context == null ? string.Empty : Context.Code;

            IsLoading = true;
            await Task.Yield();

            // 종목 변경 시작 시 이전 종목 자동매매 상태부터 차단
            if (!string.IsNullOrWhiteSpace(previousCode) && previousCode != symbol.Code)
            {
                MarkAutoTradeDataNotReady(previousCode);
                _autoTradeController?.Reset(previousCode);

                AddAutoTradeAnalysisLog(
                    $"[자동매매] 종목 변경 감지 - 이전 종목 상태 초기화: {previousCode} → {symbol.Code}");
            }

            ClearBuffer();
            OnChartResetRequired?.Invoke();

            double price = 0;
            double.TryParse(symbol.LastPrice, out price);

            Context.SwitchSymbol(symbol.Code, symbol.Name, price);

            // 새 종목은 분봉 바인딩 완료 전까지 자동매매 차단
            MarkAutoTradeDataNotReady(symbol.Code);
            _autoTradeController?.Reset(symbol.Code);

            ResetRealtimeTickWindow();
            _minuteHistoryBuffer.Clear();

            CheckHoldingStatus();

            _marketApi.ReplaceSubscription(this.WindowId, ScreenNo, symbol.Code);

            var holding = AccountHoldings?.FirstOrDefault(h => h.Code == symbol.Code);

            if (holding != null)
            {
                var store = GlobalHoldingStore.GetOrCreate(holding.Code, holding.Name);

                bool hasMinuteData;
                bool isLoading;

                lock (store.SyncRoot)
                {
                    hasMinuteData =
                        store.MinuteList.Count > 0 ||
                        store.IsMinuteHistoryLoaded ||
                        store.IsHistoryLoaded;

                    isLoading = store.IsLoadingHistory;
                }

                if (!hasMinuteData && !isLoading)
                    RequestHoldingHistoryAndRealtime(holding);

                if (hasMinuteData)
                {
                    BindHoldingStoreToChart(store, symbol);

                    IsLoading = false;
                    IsSearchPopupOpen = false;

                    AddLog($"📊 보유주 저장 데이터 바인딩: {symbol.Name}({symbol.Code})");
                    return;
                }

                if (waitHoldingLoad && isLoading)
                {
                    AddLog($"⏳ 보유주 데이터 로딩 대기: {symbol.Name}({symbol.Code})");

                    await store.HistoryLoadedSource.Task;

                    if (store.IsHistoryLoaded)
                    {
                        BindHoldingStoreToChart(store, symbol);

                        IsLoading = false;
                        IsSearchPopupOpen = false;

                        AddLog($"📊 보유주 로딩 완료 후 바인딩: {symbol.Name}({symbol.Code})");
                        return;
                    }
                }

                _ = BindHoldingStoreWhenLoadedAsync(store, symbol);

                IsLoading = false;
                IsSearchPopupOpen = false;

                AddLog($"⏳ 현재창 보유주 데이터 로딩 중: {symbol.Name}({symbol.Code})");
                return;
            }

            _marketApi.RequestMinuteCandles(
                this.WindowId,
                symbol.Code,
                ScreenNo,
                daysToLoad: 2,
                maxRows: 0,
                priority: 0);

            IsSearchPopupOpen = false;
            AddLog($"✅ 현재창 일반 종목 분봉 요청: {symbol.Name}({symbol.Code})");
        }
        private async Task BindHoldingStoreWhenLoadedAsync(HoldingSymbolContext store, Symbol symbol)
        {
            try
            {
                await store.HistoryLoadedSource.Task;

                Application.Current.Dispatcher.Invoke(() =>
                {
                    if (Context.Code != symbol.Code)
                        return;

                    if (store.IsHistoryLoaded)
                        BindHoldingStoreToChart(store, symbol);

                    IsLoading = false;
                });
            }
            catch
            {
                Application.Current.Dispatcher.Invoke(() =>
                {
                    IsLoading = false;
                });
            }
        }
        // ============================================================
        // [교체] BindHoldingStoreToChart 전체 교체
        // 보유주 차트도 이제 실시간틱이 아니라 저장된 분봉만 사용
        // ============================================================
        private void BindHoldingStoreToChart(HoldingSymbolContext store, Symbol symbol)
        {
            if (store == null || symbol == null)
                return;

            List<TrackedSymbol> chartData;
            TrackedSymbol lastMinute = null;
            TrackedSymbol lastTick = null;

            lock (store.SyncRoot)
            {
                chartData = GetChartMinuteData(store.MinuteList);

                if (chartData.Count > 0)
                    lastMinute = chartData[chartData.Count - 1];

                if (store.RecentTickList.Count > 0)
                    lastTick = store.RecentTickList[store.RecentTickList.Count - 1];
            }

            var last = lastTick ?? lastMinute;

            if (last != null)
            {
                Context.LastPrice = last.LastPrice;
                Price = last.LastPrice;
                OrderPrice = last.LastPrice;
            }

            _minuteTickBuffer.Clear();

            if (chartData.Count > 0)
            {
                _lastChartMinute = chartData[chartData.Count - 1].LastUpdated;
                _currentMinute = _lastChartMinute;

                Context.SymbolList.Clear();
                Context.SymbolList.AddRange(chartData);

                RequestChartRefresh?.Invoke(CreateChartPayload(chartData, isFullRefresh: true));
            }

            _isHistoryBindingComplete = true;
            MarkAutoTradeDataReady(symbol.Code);
            IsLoading = false;

            AddLog($"📊 보유주 분봉 차트 표시: {symbol.Name}({symbol.Code}) / 분봉 {chartData.Count}개 / 최근틱 {store.RecentTickList.Count}개");
        }
        // 보유 여부를 새로고침하는 핵심 메소드
        public void CheckHoldingStatus()
        {
            // UI 스레드에서 안전하게 실행
            App.Current.Dispatcher.Invoke(() =>
            {
                if (AccountHoldings == null || string.IsNullOrEmpty(Context.Code))
                {
                    Context.CurrentHold = null;
                    HoldingQty = 0;
                    return;
                }

                // 현재 선택된 종목(Context.Code)과 일치하는 보유 정보 탐색[cite: 2]
                var holding = AccountHoldings.FirstOrDefault(h => h.Code == Context.Code);

                if (holding != null)
                {
                    Context.CurrentHold = holding;
                    // 모델의 Quantity를 ViewModel의 HoldingQty에 동기화
                    this.HoldingQty = holding.Quantity;
                }
                else
                {
                    Context.CurrentHold = null;
                    this.HoldingQty = 0;
                }
            });
        }
        public void ClearBuffer()
