        private async Task ExecuteOpenAllHoldings()
        {
            if (AccountHoldings == null || AccountHoldings.Count == 0)
            {
                AddLog("⚠️ 조회된 보유 종목이 없어. 계좌 조회를 먼저 해줘.");
                return;
            }

            bool currentWindowUsed = !string.IsNullOrWhiteSpace(Context.Code);

            foreach (var holding in AccountHoldings.ToList())
            {
                bool isAlreadyOpen = Application.Current.Windows
                    .Cast<Window>()
                    .Any(w =>
                    {
                        if (w.DataContext is MainWindowViewModel vm)
                            return vm.Context.Code == holding.Code;

                        return (w.Tag as string) == holding.Code;
                    });

                AddLog($"[창오픈검사] {holding.Name}({holding.Code}) / already={isAlreadyOpen}");

                // 중요:
                // OpenAllHoldings에서는 이미 열린 종목으로 포커스하지 않고 그냥 건너뜀
                if (isAlreadyOpen)
                    continue;

                var symbol = new Symbol
                {
                    Code = holding.Code,
                    Name = holding.Name,
                    LastPrice = holding.CurrentPrice.ToString()
                };

                if (!currentWindowUsed)
                {
                    if (HostWindow != null)
                    {
                        HostWindow.Tag = holding.Code;
                        HostWindow.Title = $"[K-Nest] {holding.Name} ({holding.Code})";
                    }

                    Context.CurrentHold = holding;

                    // 중요:
                    // 중복창 포커스 로직을 피해야 하므로 전용 메서드 사용 권장
                    await LoadSymbolDataAsync(symbol, waitHoldingLoad: false);

                    currentWindowUsed = true;

                    AddLog($"✅ 현재 창에 미오픈 보유 종목 로딩: {holding.Name}({holding.Code})");
                }
                else
                {
                    await OpenStockWindow(holding);
                    AddLog($"✅ 새 창에 미오픈 보유 종목 로딩: {holding.Name}({holding.Code})");
                }

                await Task.Delay(200);
            }

            AddLog("✅ 모든 보유 종목 창 오픈 프로세스 완료.");
        }
        public async Task OpenStockWindow(HoldingInfo holding)
        {
            if (holding == null)
                return;

            MainWindow newWindow = new MainWindow();
            newWindow.Tag = holding.Code;

            if (newWindow.DataContext is MainWindowViewModel targetVm)
            {
                targetVm.ScreenNo = _marketApi.GetScreenNo();

                targetVm.ApplyParentAccountContext(
                    SelectedAccount,
                    CurrentBalance,
                    AccountHoldings,
                    OrderHistory);

                targetVm.Context.CurrentHold = holding;

                newWindow.Title = $"[K-Nest] {holding.Name} ({holding.Code})";
                newWindow.Show();

                await Task.Delay(500);

                var symbol = new Symbol
                {
                    Code = holding.Code,
                    Name = holding.Name,
                    LastPrice = holding.CurrentPrice.ToString()
                };

                await targetVm.LoadSymbolDataAsync(symbol, waitHoldingLoad: false);
                IsMainLoading = false;
                AddLog($"✅ 보유 종목 창 오픈 완료: {holding.Name}({holding.Code})");
            }
            else
            {
                newWindow.Close();
            }
        }
        // MainWindowViewModel.cs 내부 수정
        private void Kiwoom_OnInitialHistoryReceived(string windowId, List<TrackedSymbol> history, bool islast)
        {
            // 보유주 백그라운드 과거데이터
            if (!string.IsNullOrEmpty(windowId) && windowId.StartsWith("INV:"))
            {
                HandleHoldingHistory(windowId, history, islast);
                return;
            }

            // 일반 창 전용 과거데이터
            if (this.WindowId != windowId)
                return;

            Application.Current.Dispatcher.Invoke(() =>
            {
                OnInitialHistoryReceived_Handler(history, islast);
            });
        }
        private void HandleHoldingHistory(string windowId, List<TrackedSymbol> history, bool islast)
        {
            string code = windowId.Replace("INV:", "");
            var store = GlobalHoldingStore.GetOrCreate(code);

            lock (store.SyncRoot)
            {
                int receivedCount = history == null ? 0 : history.Count;

                if (history != null && history.Count > 0)
                {
                    foreach (var tick in history)
                        store.SymbolList.Add(tick);
                }

                //Debug.WriteLine(
                //    $"✅ 보유주 과거데이터 종목코드[{code}] 수신 {receivedCount}개 / 총 {store.SymbolList.Count}개 / islast={islast}"
                //);

                if (!islast)
                    return;

                // 키움 과거데이터는 보통 최신 → 과거 순서
                // 전체 정렬 대신 한 번만 뒤집어서 과거 → 최신 순서로 만든다
                store.SymbolList.Reverse();

                if (store.SymbolList.Count > 0)
                    store.LastTickTime = store.SymbolList[store.SymbolList.Count - 1].LastUpdated;

                while (store.PendingTicks.Count > 0)
                {
                    var pending = store.PendingTicks.Dequeue();

                    if (pending.LastUpdated < store.LastTickTime)
                        continue;

                    store.SymbolList.Add(pending);

                    if (pending.LastUpdated > store.LastTickTime)
                        store.LastTickTime = pending.LastUpdated;
                }

                // 분봉도 여기서 한 번만 생성
                store.MinuteList.Clear();
                store.MinuteList.AddRange(AggregateToMinuteBars(store.SymbolList));

                store.IsHistoryLoaded = true;
                store.IsLoadingHistory = false;
                store.HistoryLoadedSource.TrySetResult(true);
            }

            Application.Current.Dispatcher.Invoke(() =>
            {
                var holding = AccountHoldings.FirstOrDefault(x => x.Code == code);

                if (holding != null)
                {
                    holding.IsHistoryLoading = false;
                    holding.IsHistoryLoaded = true;
                }
            });

            AddLog($"✅ 보유주 과거데이터 저장 완료: {code}");
        }
        private void UpdateAutoTradePositionsFromHoldings(List<HoldingInfo> holdings)
        {
            if (_autoTradeController == null)
                return;

            var currentCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (holdings != null)
            {
                foreach (var holding in holdings)
                {
                    if (holding == null || string.IsNullOrWhiteSpace(holding.Code))
                        continue;

                    currentCodes.Add(holding.Code);

                    _autoTradeController.UpdatePosition(
                        holding.Code,
                        Math.Max(0, holding.Quantity),
                        holding.EntryPrice);
                }
            }

            // 보유종목 응답에서 사라진 종목은 전량매도/잔고 0으로 Core에 반드시 반영한다.
            // 이 처리가 빠지면 Core는 계속 보유 중으로 판단하고, 자산배분도 사용금액을 잘못 잡는다.
            foreach (var oldCode in _lastAutoTradeHoldingCodes.ToList())
            {
                if (string.IsNullOrWhiteSpace(oldCode))
                    continue;

                if (currentCodes.Contains(oldCode))
                    continue;

                _autoTradeController.UpdatePosition(oldCode, 0, 0);
            }

            _lastAutoTradeHoldingCodes.Clear();
            foreach (var code in currentCodes)
                _lastAutoTradeHoldingCodes.Add(code);
        }

        private void ApplyHoldingsToUi(List<HoldingInfo> holdings)
        {
            AccountHoldings.Clear();

            foreach (var holding in holdings)
            {
                if (holding == null || string.IsNullOrWhiteSpace(holding.Code))
                    continue;

                var store = GlobalHoldingStore.GetOrCreate(holding.Code, holding.Name);

                holding.IsHistoryLoaded = store.IsHistoryLoaded;
                holding.IsHistoryLoading = store.IsLoadingHistory;

                AccountHoldings.Add(holding);
            }

            if (Context != null && !string.IsNullOrWhiteSpace(Context.Code))
            {
                var currentHolding = AccountHoldings.FirstOrDefault(x => x.Code == Context.Code);

                Context.CurrentHold = currentHolding;
                HoldingQty = currentHolding != null ? currentHolding.Quantity : 0;

                _autoTradeController?.UpdatePosition(
                    Context.Code,
                    HoldingQty,
                    currentHolding == null ? 0 : currentHolding.EntryPrice);
            }
            else
            {
                HoldingQty = 0;
            }

            OnPropertyChanged(nameof(AccountHoldings));
            OnPropertyChanged(nameof(HoldingQty));
            OnPropertyChanged(nameof(TradeCardHoldingQty));
        }

        private void Kiwoom_OnHoldingsReceived(string windowId, List<HoldingInfo> holdings)
        {
            CompleteInitialMainLoadingToken("HOLDINGS");

            // 전량매도 직후 키움/서비스 구현에 따라 null이 들어올 수 있다.
            // null을 그대로 return 하면 기존 보유목록이 화면/Core에 남아서
            // 보유종목 UI 갱신과 자산배분의 보유금액 차감이 모두 틀어진다.
            var safeHoldings = holdings ?? new List<HoldingInfo>();

            Application.Current.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    ApplyHoldingsToUi(safeHoldings);
                    UpdateAutoTradePositionsFromHoldings(safeHoldings);
                    SyncAutoTradeState("보유종목 갱신");
                }));
        }

