            if (orderType.Contains("매수") && orderType.Contains("취소"))
                return "매수취소";

            if (orderType.Contains("매도") && orderType.Contains("취소"))
                return "매도취소";

            if (orderType.Contains("매수") && orderType.Contains("정정"))
