            return new TickFrame
            {
                Code = x.Code,
                Time = x.Time,
                Open = x.Open,
                High = x.High,
                Low = x.Low,
                Close = x.Close,
                Volume = x.Volume,
                AccumulatedVolume = x.AccumulatedVolume,
                AvgStrength = x.AvgStrength,
                LastStrength = x.LastStrength,
                TotalAskQty = x.TotalAskQty,
                TotalBidQty = x.TotalBidQty,
                TickCount = x.TickCount,
                BuyTickCount = x.BuyTickCount,
                SellTickCount = x.SellTickCount,
                UpdatedAt = x.UpdatedAt
            };
        }

        private static TrackedSymbol CloneTrackedSymbolForAutoTrade(TrackedSymbol x)
        {
            if (x == null)
                return null;

            return new TrackedSymbol
            {
                Code = x.Code,
                LastPrice = x.LastPrice,
                LastVolume = x.LastVolume,
                ClosePrice = x.ClosePrice,
                HighPrice = x.HighPrice,
                LowPrice = x.LowPrice,
                AccumulatedVolume = x.AccumulatedVolume,
                TotalAskQty = x.TotalAskQty,
                TotalBidQty = x.TotalBidQty,
                Strength = x.Strength,
                Side = x.Side,
                LastUpdated = x.LastUpdated
            };
        }

